from taf.collectors.l1l2bip.collector import L1L2BIPCollector, ASODL1L2BIPCollector, GenericL1L2BIPCollector, \
    AirphoneL1L2BIPCollector, SbtsInterfaceMirroringL1L2BIPCollector, VduInterfaceMirroringL1L2BIPCollector
from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.core.factories.named_factory import NamedComponentFactory
from taf.collectors.core.factories.collector_factory import CoamSbtsCollectorFactory, VduCollectorFactory

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class L1L2BIPCollectorFactoryBase(Creating("tool_executor", "SshExecutor", "executor"),
                                  NamedComponentFactory):
    pass


class L1L2BIPCollectorFactory(Creating("file_putter", "SshFilePutter", "executor"),
                              L1L2BIPCollectorFactoryBase):
    """
    Factory to create L1/L2 BIP collectors
    """
    _product_class = L1L2BIPCollector
    _optional_parameters = {"gnb_mirroring_path", "gnb_mirroring_config_path", "enable_syscom_mirroring",
                            "mirror_capacity_units", "carrier_aggregation", "mirroring_mode", "script_dir"}


class ASODL1L2BIPCollectorFactory(Creating("file_putter", "SshFilePutter", "executor"),
                                  L1L2BIPCollectorFactoryBase):
    """
    Factory to create ASOD L1/L2 BIP collectors
    """

    _product_class = ASODL1L2BIPCollector
    _optional_parameters = {"asod_mirroring_path", "script_dir"}


class GenericL1L2BIPCollectorFactory(L1L2BIPCollectorFactoryBase):
    """
    Factory to create Generic L1/L2 BIP collectors
    """

    _product_class = GenericL1L2BIPCollector
    _optional_parameters = {"setup_commands", "teardown_commands"}


class InterfaceMirroringL1L2BIPCollectorFactoryBase(Creating("local_executor", "LocalExecutor")):
    """
    Factory base class to create interface mirroring L1/L2 BIP collectors
    """
    _optional_parameters = {"interface", "nr_phy_cell_ids", "nr_cell_dns", "remove_zip_file", "timeout"}


class InterfaceL1L2BIPCollectorFactory(InterfaceMirroringL1L2BIPCollectorFactoryBase,
                                       CoamSbtsCollectorFactory):
    """
    Factory to create interface mirroring L1/L2 BIP collectors
    """
    _product_class = SbtsInterfaceMirroringL1L2BIPCollector
    _optional_parameters = {"destination", "target_file_name", "merge_pcap_files", "parallel_mirroring",
                            "mirroring_filter", "specific_message_ids"}


class AirphoneL1L2BIPCollectorFactory(Creating("file_putter", "SshFilePutter", "executor"),
                                      L1L2BIPCollectorFactoryBase):
    """
    Factory to create Airphone L1/L2 BIP collectors.
    """
    _product_class = AirphoneL1L2BIPCollector
    _mandatory_parameters = {"script_paths"}
    _optional_parameters = {"command_line", "script_dir"}


class VduInterfaceMirroringL1L2BIPCollectorFactory(InterfaceMirroringL1L2BIPCollectorFactoryBase, VduCollectorFactory):
    """
    Factory to create VDU interface mirroring L1/L2 BIP collectors
    """
    _product_class = VduInterfaceMirroringL1L2BIPCollector
